      else if (name == 'light') { inside = labL >= 0.72; core = (labL - 0.72) / 0.28; }
      else if (name == 'bright') { inside = high >= 0.72 && labL >= 0.55; core = (high - 0.72) / 0.28; }
      else if (name == 'vivid') { inside = hsvS >= 0.55 && high >= 0.5; core = (hsvS - 0.55) / 0.45 * (high - 0.5) / 0.5; }
